import { Component, OnInit } from '@angular/core';
import { ZahteviService, UnifiedZahtevResponse } from '../../services/zahtevi.service';
import {AuthService} from "../../services/auth.service";

interface UnifiedItem {
  id: string | number;
  tip: string;
  status?: string;
  datumPodnosenja?: string;
  dodatniPodaci?: string;
}

@Component({
  selector: 'app-ostalo',
  templateUrl: './ostalo.component.html',
  styleUrls: ['./ostalo.component.css']
})
export class OstaloComponent implements OnInit {
  zahtevi: UnifiedItem[] = [];
  message = '';
  rola: string = '';

  constructor(private zahteviService: ZahteviService,private authService: AuthService) {}

  ngOnInit(): void {
    this.ucitajZahteve();
    this.rola = this.authService.getRoleFromToken();
  }

  selectedDokument: string = '';
  aktivniDokumenti: UnifiedItem[] = [];
  noviZahtev: { tip: string; datumPrijave: string } = { tip: '', datumPrijave: '' };

  ucitajZahteve(): void {
    this.message = 'Učitavam...';
    this.zahteviService.getMojiZahtevi().subscribe({
      next: (data) => {
        this.zahtevi = this.normalize(data);
        this.sortByDateDesc();
        this.aktivniDokumenti = this.zahtevi.filter(z => z.status === 'DOZVOLJEN'); // samo aktivni dokumenti
        this.message = `Učitano ${this.zahtevi.length} zahteva.`;
      },
      error: (err) => {
        this.message = `Greška: ${err.message}`;
      }
    });
  }

// metoda za prijavu izgubljenog dokumenta
  prijaviIzgubljeniDokument(): void {
    if (!this.selectedDokument) return;

    const danasnjiDatum = new Date().toISOString().split('T')[0];

    const payload = {
      tip: this.selectedDokument,
      datumPrijave: danasnjiDatum
    };


  }

  private sortByDateDesc(): void {
    this.zahtevi.sort((a, b) => {
      const dateA = a.datumPodnosenja ? new Date(a.datumPodnosenja).getTime() : 0;
      const dateB = b.datumPodnosenja ? new Date(b.datumPodnosenja).getTime() : 0;
      return dateB - dateA; // najnoviji datum prvi
    });
  }


  private normalize(data: UnifiedZahtevResponse): UnifiedItem[] {
    const out: UnifiedItem[] = [];

    (data.licne_karte || []).forEach(x =>
      out.push({
        id: x.id ?? 'n/a',
        tip: 'Lična karta',
        status: x.status,
        datumPodnosenja: x.datumIzdavanja // koristimo datum izdavanja (početni datum)
      })
    );

    (data.oruzje || []).forEach(x =>
      out.push({
        id: x.id ?? 'n/a',
        tip: 'Oružje',
        status: x.status,
        datumPodnosenja: x.datumOd // početni datum važenja
      })
    );

    (data.saobracajne_dozvole || []).forEach(x =>
      out.push({
        id: x.id ?? 'n/a',
        tip: 'Saobraćajna dozvola',
        status: x.status,
        datumPodnosenja: x.datumIzdavanja // početni datum važenja
      })
    );

    (data.vozacke_dozvole || []).forEach(x =>
      out.push({
        id: x.id ?? 'n/a',
        tip: 'Vozačka dozvola',
        status: x.status,
        datumPodnosenja: x.datumIzdavanja // početni datum važenja
      })
    );

    return out;
  }

  get isEmployer(): boolean {
    return this.rola === 'EMPLOYER';
  }

}
<div class="container mt-4" *ngIf="!isEmployer">
  <h2 class="mb-3 text-center">📋 Moji zahtevi</h2>



  <!-- Tabela mojih zahteva -->
  <div class="table-responsive" *ngIf="zahtevi.length > 0; else nemaZahteva">
    <table class="table table-striped table-hover table-bordered align-middle shadow-sm">
      <thead class="table-primary text-center">
      <tr>
        <th scope="col">#</th>
        <th scope="col">Tip</th>
        <th scope="col">Status</th>
        <th scope="col">Datum slanja</th>
      </tr>
      </thead>
      <tbody>
      <tr *ngFor="let z of zahtevi; let i = index" class="text-center">
        <td>{{ i + 1 }}</td>
        <td><span class="badge bg-secondary">{{ z.tip }}</span></td>
        <td>
            <span [ngClass]="{
              'badge bg-success': z.status === 'ODOBREN',
              'badge bg-danger': z.status === 'ODBIJEN',
              'badge bg-warning text-dark': z.status === 'NA ČEKANJU'
            }">
              {{ z.status }}
            </span>
        </td>
        <td>{{ z.datumPodnosenja | date: 'dd.MM.yyyy' }}</td>
      </tr>
      </tbody>
    </table>
  </div>
  <!-- Prijava izgubljenog dokumenta -->
  <div class="card mb-4">
    <div class="card-body">
      <h5 class="card-title">Prijava izgubljenog dokumenta</h5>
      <div class="d-flex align-items-center">
        <select class="form-select me-2" [(ngModel)]="selectedDokument" name="selectedDokument">
          <option value="" disabled selected>Izaberite dokument</option>
          <option *ngFor="let doc of aktivniDokumenti" [value]="doc.tip">{{ doc.tip }}</option>
        </select>
        <button class="btn btn-danger" (click)="prijaviIzgubljeniDokument()" [disabled]="!selectedDokument">
          Prijavi
        </button>
      </div>
    </div>
  </div>
  <ng-template #nemaZahteva>
    <p class="text-center text-muted mt-4">Nema pronađenih zahteva.</p>
  </ng-template>
</div>
